export async function retry<T>(
  task: () => Promise<T>,
  attempts = 3,
  baseDelay = 220,
): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await task();
    } catch (error) {
      lastError = error;
      const jitter = Math.random() * 80;
      await new Promise((r) => setTimeout(r, baseDelay * 2 ** i + jitter));
    }
  }
  throw lastError;
}

